const VERSION='anatomy-v5';
self.addEventListener('install',e=>{e.waitUntil((async()=>{const manifest=await fetch('./offline-assets.json').then(r=>r.json());const cache=await caches.open(VERSION+'-core');await cache.addAll(manifest.core);await self.skipWaiting();})());});
self.addEventListener('activate',e=>e.waitUntil((async()=>{const names=await caches.keys();const core=await caches.open(VERSION+'-core');const manifest=await (await core.match('./offline-assets.json')).json();
// The v5 model binaries are identical to v4. Preserve explicitly downloaded models.
for(const sex of ['male','female'])if(names.includes('anatomy-v4-'+sex)){const old=await caches.open('anatomy-v4-'+sex),next=await caches.open(VERSION+'-'+sex);for(const url of manifest[sex]){const hit=await old.match(url);if(hit)await next.put(url,hit);}}
for(const key of names)if(key.startsWith('anatomy-')&&!key.startsWith(VERSION))await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith((async()=>{const hit=await caches.match(e.request,{ignoreSearch:true});if(hit)return hit;try{return await fetch(e.request);}catch(err){if(e.request.mode==='navigate'){const cache=await caches.open(VERSION+'-core');const page=await cache.match('./index.html');if(page)return page;}throw err;}})());});
self.addEventListener('message',e=>{if(e.data?.type!=='download')return;const port=e.ports[0];e.waitUntil((async()=>{try{if(!['male','female'].includes(e.data.sex))throw Error('Geçersiz model');const core=await caches.open(VERSION+'-core');const manifest=await (await core.match('./offline-assets.json')||await fetch('./offline-assets.json')).json();const files=manifest[e.data.sex];const cache=await caches.open(VERSION+'-'+e.data.sex);let done=0;for(const url of files){if(!await cache.match(url)){const response=await fetch(url);if(!response.ok)throw Error('Model dosyası indirilemedi');await cache.put(url,response);}port.postMessage({type:'progress',done:++done,total:files.length});}port.postMessage({type:'done',sex:e.data.sex});}catch(err){port.postMessage({type:'error',message:err.message});}})());});
